# -*- coding: utf-8 -*-
r"""
V9.4 - QUẢN LÝ / NHẬP PHƯƠNG ÁN SÁP NHẬP THEO VĂN BẢN
=========================================================

NỀN CÀI:
- Được tạo trực tiếp từ mã nguồn sau V9.3.1 do người dùng gửi ngày 03/09/2026.
- Installer kiểm tra SHA256 của 3 file hiện tại trước khi ghi.
- Nếu mã nguồn không khớp, DỪNG AN TOÀN, không vá đoán.

BỔ SUNG:
1. Nút "Quản lý / nhập phương án theo văn bản" tại màn hình Sáp nhập trường.
2. Trang:
   /cong-cu-du-lieu/sap-nhap-truong/phuong-an
3. Luồng bắt buộc:
   NHÁP -> kiểm tra kỹ thuật/mô phỏng RAM -> PHÊ DUYỆT
   -> mới xuất hiện ở màn hình thực hiện sáp nhập.
4. Nhập:
   - Năm học
   - Xã/phường (tìm nhanh bằng cách gõ từ đầu)
   - Cấp học
   - Số/Ký hiệu văn bản
   - Ngày văn bản
   - Tên/nội dung văn bản
   - Nhiều trường nguồn
   - Một trường đích
   - Ghi chú
5. An toàn:
   - nguồn/đích phải cùng xã và đúng cấp học;
   - nguồn/đích phải đang hoạt động khi lập phương án mới;
   - không trùng nguồn với đích;
   - không trùng exact plan;
   - không để một trường nằm trong 2 phương án APPROVED cùng năm;
   - phê duyệt chỉ thành công sau integrity check + mô phỏng SQLite RAM;
   - plan COMPLETED không sửa/hủy/chạy lại;
   - DRAFT mới được sửa/xóa;
   - APPROVED có thể hủy bằng câu xác nhận.
6. Mỗi mutation file phương án đều tự backup JSON cũ vào C:\PhoCap\backups.

KHÔNG SỬA DATABASE KHI CÀI V9.4.
"""

from __future__ import annotations

import ast
import base64
import hashlib
import json
import shutil
import sys
import zlib
import zipfile
from datetime import datetime
from pathlib import Path

ROOT = Path(r"C:\PhoCap")
SERVICE = ROOT / "app" / "services" / "school_merger_service.py"
ROUTER = ROOT / "app" / "routers" / "school_merger.py"
MAIN_TEMPLATE = ROOT / "app" / "templates" / "data_tools" / "school_merger.html"
PLANS_TEMPLATE = ROOT / "app" / "templates" / "data_tools" / "school_merger_plans.html"
PLAN_FILE = ROOT / "data" / "school_merger_approved_plans.json"
EXPORTS = ROOT / "exports"

EXPECTED = {
    str(SERVICE): 'bf2ff5a9746a36aeb7cd94bcad7ec961eaa2573abeba953afa4cbf42bc0bde83',
    str(ROUTER): 'a6c33b8cdd912893812ef69db065231f6c5129af171252752dddd1e38e48fa68',
    str(MAIN_TEMPLATE): 'bc7dcdb9a7faf16637516d7c670466db387f3ae70d8b4e269e41a9fdcae9ccac',
}

BLOBS = {
    str(SERVICE): '',
    str(ROUTER): '',
    str(MAIN_TEMPLATE): '',
    str(PLANS_TEMPLATE): '',
}


def decode(value: str) -> bytes:
    return zlib.decompress(base64.b64decode(value.encode("ascii")))


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def fail(message: str, code: int = 2) -> None:
    print("=" * 112)
    print("DỪNG AN TOÀN V9.4")
    print("=" * 112)
    print(message)
    print("Database KHÔNG bị thay đổi.")
    raise SystemExit(code)


def restore(backup_dir: Path, plans_existed: bool) -> None:
    for target in (SERVICE, ROUTER, MAIN_TEMPLATE):
        b = backup_dir / target.name
        if b.exists():
            shutil.copy2(b, target)

    b_new = backup_dir / PLANS_TEMPLATE.name
    if b_new.exists():
        shutil.copy2(b_new, PLANS_TEMPLATE)
    elif PLANS_TEMPLATE.exists():
        try:
            PLANS_TEMPLATE.unlink()
        except Exception:
            pass

    plan_backup = backup_dir / PLAN_FILE.name
    if plans_existed and plan_backup.exists():
        shutil.copy2(plan_backup, PLAN_FILE)


def main() -> None:
    for target in (SERVICE, ROUTER, MAIN_TEMPLATE):
        if not target.exists():
            fail(f"Không tìm thấy file nền V9.3.1: {target}")

    # Cổng hash: không cài lên một bản nguồn khác.
    mismatches = []
    for path_text, expected in EXPECTED.items():
        path = Path(path_text)
        actual = sha(path)
        if actual != expected:
            mismatches.append(
                f"{path}\n  expected={expected}\n  actual  ={actual}"
            )
    if mismatches:
        fail(
            "Mã nguồn hiện tại đã khác ZIP sau V9.3.1 dùng để tạo V9.4. "
            "Không vá đoán.\n\n" + "\n\n".join(mismatches),
            3,
        )

    # Kiểm tra file phương án hiện tại trước khi chạm mã nguồn.
    plans_existed = PLAN_FILE.exists()
    if plans_existed:
        try:
            payload = json.loads(PLAN_FILE.read_text(encoding="utf-8"))
        except Exception as exc:
            fail(f"File phương án hiện tại không đọc được: {exc}", 4)
        if not isinstance(payload, dict) or not isinstance(payload.get("plans"), list):
            fail("File phương án hiện tại không đúng cấu trúc {version, plans:[...]}.", 4)

    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_dir = EXPORTS / f"backup_sap_nhap_v9_4_{stamp}"
    backup_dir.mkdir(parents=True, exist_ok=False)

    shutil.copy2(SERVICE, backup_dir / SERVICE.name)
    shutil.copy2(ROUTER, backup_dir / ROUTER.name)
    shutil.copy2(MAIN_TEMPLATE, backup_dir / MAIN_TEMPLATE.name)
    if PLANS_TEMPLATE.exists():
        shutil.copy2(PLANS_TEMPLATE, backup_dir / PLANS_TEMPLATE.name)
    if PLAN_FILE.exists():
        shutil.copy2(PLAN_FILE, backup_dir / PLAN_FILE.name)

    try:
        SERVICE.write_bytes(decode(BLOBS[str(SERVICE)]))
        ROUTER.write_bytes(decode(BLOBS[str(ROUTER)]))
        MAIN_TEMPLATE.write_bytes(decode(BLOBS[str(MAIN_TEMPLATE)]))
        PLANS_TEMPLATE.write_bytes(decode(BLOBS[str(PLANS_TEMPLATE)]))

        # Cú pháp Python.
        ast.parse(SERVICE.read_text(encoding="utf-8"))
        ast.parse(ROUTER.read_text(encoding="utf-8"))

        # Jinja.
        try:
            from jinja2 import Environment
            env = Environment()
            env.parse(MAIN_TEMPLATE.read_text(encoding="utf-8"))
            env.parse(PLANS_TEMPLATE.read_text(encoding="utf-8"))
            jinja_result = "PASS"
        except ImportError:
            jinja_result = "SKIP - jinja2 không có trong Python installer"

        checks = {
            "service V9.4 plan manager": "save_merger_plan_draft" in SERVICE.read_text(encoding="utf-8"),
            "approval technical simulation": "_technical_check_plan_for_approval" in SERVICE.read_text(encoding="utf-8"),
            "router manager": '@router.get("/phuong-an"' in ROUTER.read_text(encoding="utf-8"),
            "main link": "Quản lý / nhập phương án theo văn bản" in MAIN_TEMPLATE.read_text(encoding="utf-8"),
            "manager template": "Kiểm tra & PHÊ DUYỆT" in PLANS_TEMPLATE.read_text(encoding="utf-8"),
            "commune quick search": "plan-commune-search" in PLANS_TEMPLATE.read_text(encoding="utf-8"),
        }
        failed = [name for name, ok in checks.items() if not ok]
        if failed:
            raise RuntimeError("Thiếu marker sau cài: " + ", ".join(failed))

        # V9.4 KHÔNG được thay đổi file plan khi chỉ cài mã nguồn.
        if plans_existed:
            before = (backup_dir / PLAN_FILE.name).read_bytes()
            after = PLAN_FILE.read_bytes()
            if before != after:
                raise RuntimeError("Installer đã làm thay đổi file phương án ngoài dự kiến.")

    except Exception as exc:
        restore(backup_dir, plans_existed)
        print("=" * 112)
        print("CÀI V9.4 THẤT BẠI - ĐÃ TỰ KHÔI PHỤC MÃ NGUỒN")
        print("=" * 112)
        print(repr(exc))
        print("Database KHÔNG bị thay đổi.")
        raise SystemExit(5)

    report = backup_dir / "00_KET_QUA_CAI_DAT_V9_4.txt"
    report.write_text(
        "\n".join([
            "V9.4 - QUẢN LÝ / NHẬP PHƯƠNG ÁN SÁP NHẬP THEO VĂN BẢN",
            "=" * 100,
            "STATUS=SUCCESS",
            "Database=KHÔNG THAY ĐỔI",
            "File phương án hiện có=KHÔNG THAY ĐỔI KHI CÀI",
            f"Backup mã nguồn={backup_dir}",
            f"Jinja={jinja_result}",
            "",
            "Đã thêm:",
            "- /cong-cu-du-lieu/sap-nhap-truong/phuong-an",
            "- NHÁP -> kiểm tra/mô phỏng -> PHÊ DUYỆT -> thực hiện",
            "- Tìm nhanh xã/phường",
            "- Chọn nhiều nguồn bằng checkbox, một đích bằng radio",
            "- Sửa/xóa chỉ DRAFT",
            "- Hủy DRAFT/APPROVED",
            "- APPROVED mới xuất hiện ở màn hình thực hiện",
            "- Mutation plan JSON có backup nguyên tử",
        ]),
        encoding="utf-8",
    )

    result_zip = ROOT / f"ket_qua_cai_dat_sap_nhap_v9_4_{stamp}.zip"
    with zipfile.ZipFile(result_zip, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        zf.write(report, arcname=report.name)
        if PLAN_FILE.exists():
            zf.write(PLAN_FILE, arcname=PLAN_FILE.name)
        for target in (SERVICE, ROUTER, MAIN_TEMPLATE):
            zf.write(backup_dir / target.name, arcname="TRUOC_V9_4/" + target.name)

    print("=" * 112)
    print("CÀI ĐẶT V9.4 THÀNH CÔNG")
    print("=" * 112)
    print("Database: KHÔNG THAY ĐỔI")
    print("File phương án hiện có: KHÔNG THAY ĐỔI KHI CÀI")
    print(f"Backup mã nguồn: {backup_dir}")
    print(f"Jinja parse: {jinja_result}")
    print("Đã thêm: Quản lý / nhập phương án theo văn bản")
    print("Luồng: NHÁP -> KIỂM TRA/MÔ PHỎNG -> PHÊ DUYỆT -> SÁP NHẬP")
    print("Phương án APPROVED mới xuất hiện ở màn hình thực hiện.")
    print(f"ZIP kết quả: {result_zip}")


if __name__ == "__main__":
    main()
